const stockName=n=>norm(n)==='MICROFIBRA LEVE'?'FORRO LEVE':norm(n);
function ensureInitialInventory(){
  db.products=db.products||[];
  for(const [type,name,colors] of STOCK_SEED){
    for(const color of colors){
      const exists=db.products.some(p=>p.stockManaged&&norm(p.type)===norm(type)&&stockName(p.name)===stockName(name)&&norm(p.color)===norm(color));
      if(!exists) db.products.push({id:uid(),code:'EST-'+String(db.products.length+1).padStart(4,'0'),type,category:'ESTOQUE PADRÃO',name,color,qty:500,cost:0,markup:80,unit:'M',stockManaged:true,createdAt:new Date().toISOString()});
    }
  }
}
function findStockProduct(type,name,color){return (db.products||[]).find(p=>p.stockManaged&&norm(p.type)===norm(type)&&stockName(p.name)===stockName(name)&&norm(p.color)===norm(color))}
function stockRequirements(q){const req=[];for(const e of q.environments||[]){const c=calcEnvironment(e);if(!c)continue;if(c.finishCalc)req.push({type:'TECIDO DE ACABAMENTO',name:e.finish,color:e.finishColor,qty:c.finishCalc.consumption,environment:e.name});if(c.liningCalc)req.push({type:'TECIDO DE FORRO',name:e.lining,color:e.liningColor,qty:c.liningCalc.consumption,environment:e.name})}return req}
function validateAndConsumeStock(q,order){
  const req=stockRequirements(q), grouped={};
  for(const r of req){const key=[r.type,stockName(r.name),norm(r.color)].join('|');grouped[key]??={...r,qty:0};grouped[key].qty+=Number(r.qty||0)}
  for(const r of Object.values(grouped)){const p=findStockProduct(r.type,r.name,r.color);if(!p)return {ok:false,error:`Produto de estoque não encontrado: ${r.name} / ${r.color}.`};if(Number(p.qty||0)+1e-9<r.qty)return {ok:false,error:`Estoque insuficiente de ${r.name} / ${r.color}. Necessário ${r.qty.toFixed(2)} m; disponível ${Number(p.qty||0).toFixed(2)} m.`}}
  order.stockMovements=[];
  for(const r of Object.values(grouped)){const p=findStockProduct(r.type,r.name,r.color);p.qty=Number(p.qty||0)-r.qty;order.stockMovements.push({productId:p.id,type:r.type,name:r.name,color:r.color,qty:r.qty,unit:'M'})}
  return {ok:true};
}
function restoreOrderStock(order){if(order?.stockRestored)return;for(const m of order?.stockMovements||[]){const p=(db.products||[]).find(x=>x.id===m.productId)||findStockProduct(m.type,m.name,m.color);if(p)p.qty=Number(p.qty||0)+Number(m.qty||0)}order.stockRestored=true}
const STAGES=['RECEPÇÃO','CORTE','COSTURA','BARRA','PASSADORIA','EXPEDIÇÃO'];
const NAV=[
  ['quote','Novo orçamento','all'],['quotes','Orçamentos','all'],['clients','Clientes','sales'],['orders','Pedidos','all'],['production','Produção','production'],['install','Instalações','all'],['inventory','Estoque','gestor'],['pricing','Tabela / Preços','gestor'],['kpis','KPIs','gestor'],['payables','Contas a pagar','gestor'],['suppliers','Compras / Fornecedores','gestor'],['rework','Retrabalho','all'],['users','Usuários','gestor']
];
